    /// A cold encoder and a paraphrase share no word, so the atom list
    /// recalls nothing. The prompt waits until status says the encoder
    /// has answered, then the search is what the prompt hears.
    #[test]
    fn a_cold_first_prompt_waits_and_recalls_a_paraphrase() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let _env = env_guard();
        let runtime = tempfile::tempdir().unwrap();
        let config = tempfile::tempdir().unwrap();
        let _hold = HoldEnv::set(&[
            ("XDG_RUNTIME_DIR", runtime.path().to_str().unwrap()),
            ("XDG_CONFIG_HOME", config.path().to_str().unwrap()),
        ]);
        let memory = "Push a tag with git push origin TAG; follow-tags skips lightweight tags.";
        let statuses = Arc::new(AtomicUsize::new(0));
        let seen = Arc::clone(&statuses);
        let (url, _) = serve_http(move |req| {
            let first = req.lines().next().unwrap_or("");
            if first.contains("/v1/status") {
                let n = seen.fetch_add(1, Ordering::SeqCst);
                let answering = if n == 0 {
                    serde_json::Value::Null
                } else {
                    serde_json::Value::Bool(true)
                };
                return (
                    200,
                    serde_json::json!({"embedder": {"available": true, "answering": answering}})
                        .to_string(),
                );
            }
            if first.contains("/v1/atoms") {
                return (
                    200,
                    serde_json::json!({"atoms": [{
                        "id": "atom-tag",
                        "kind": "preference",
                        "text": memory,
                        "entities": ["horizon:standing"],
                        "source": {"basis": "person"},
                        "ts": "2020-01-01T00:00:00Z"
                    }]})
                    .to_string(),
                );
            }
            if first.contains("/v1/search") {
                return (
                    200,
                    serde_json::json!({"hits": [{
                        "id": "atom-tag",
                        "text": memory,
                        "score": 2.0,
                        "kind": "preference",
                        "ts": "2020-01-01T00:00:00.000Z",
                        "entities": ["horizon:standing"],
                        "source": {"basis": "person"},
                        "ballots": 2,
                        "of": 3,
                        "dense_rank": 1,
                        "cosine": 0.8
                    }]})
                    .to_string(),
                );
            }
            (200, r#"{"hits":[]}"#.into())
        });
        let _url = PackUrl::set(&url);
        let call = HookCall {
            event: "UserPromptSubmit".into(),
            cue: "How should a release identifier be published?".into(),
            session: Some("cold-paraphrase".into()),
            shape: HookShape::default(),
        };
        let started = std::time::Instant::now();
        let (note, _) = hook_note(&call, 5);
        assert!(
            started.elapsed() < std::time::Duration::from_secs(3),
            "the wait ran past its bound: {note}"
        );
        assert!(
            note.contains("follow-tags skips lightweight tags"),
            "the first prompt carried no memory: {note}"
        );
        assert!(
            !note.contains(ENCODER_WARMING_NOTE),
            "the warming line hid the memory: {note}"
        );
        assert!(
            statuses.load(Ordering::SeqCst) >= 2,
            "status was not polled until the encoder answered"
        );
    }

    #[test]
    fn the_hook_keeps_what_two_scorers_agreed_on() {
        let hit = |ballots, of| Hit {
            id: None,
            text: "x".into(),
            score: 1.0,
            kind: "lesson".into(),
            ts: None,
            entities: vec![],
            ballots,
            of,
        };
        assert!(agreed(&hit(Some(2), Some(3))));
        assert!(!agreed(&hit(Some(1), Some(3))));
        assert!(agreed(&hit(Some(1), Some(1))));
        assert!(agreed(&hit(None, None)));
        assert!(names_the_cue(
            "OpenCPMD Fortran calls the rgsaddle band API.",
            "plot the eon outputs with opencpmd and chemparseplot"
        ));
        assert!(!names_the_cue(
            "A submitted CQA packet uses the reviewer-edited Org quotes.",
            "plot the eon outputs with chemparseplot"
        ));
        assert!(!names_the_cue(
            "A doc comment states what an item does and one why.",
            "why are you not making real images"
        ));
        assert!(!names_the_cue("The fuse default is CombMNZ.", "why"));
        assert!(!names_a_numbered_pr(
            "A PR branch has to contain main before it merges."
        ));
        assert!(names_a_numbered_pr(
            "Pull requests 32 and 36 share one tree, and PR 32 replays PR 36."
        ));
        assert!(names_a_numbered_pr("rgpot #80 left a sibling behind main."));
        assert!(!names_a_numbered_pr(
            "The prompt hook holds the pack note until the first tool result."
        ));
        assert!(is_transient(
            "Pull requests 32 and 36 share one tree, and PR 32 replays PR 36."
        ));
        assert!(is_transient("The closure is on demo-wgo8."));
        assert!(is_transient("The sweep was commit 80c73416c."));
        assert!(!is_transient(
            "A PR branch has to contain main before it merges."
        ));
        assert!(!is_transient("The prompt hook holds the pack note."));
        let standing = Hit {
            id: None,
            text: "Pull requests 32 and 36 share one tree.".into(),
            score: 1.0,
            kind: "lesson".into(),
            ts: None,
            entities: vec!["horizon:standing".into()],
            ballots: None,
            of: None,
        };
        assert!(is_refresher(&standing));
        let tagged = Hit {
            id: None,
            text: "A PR branch has to contain main.".into(),
            score: 1.0,
            kind: "lesson".into(),
            ts: None,
            entities: vec!["horizon:transient".into()],
            ballots: None,
            of: None,
        };
        assert!(!is_refresher(&tagged));
        let untagged = Hit {
            id: None,
            text: "A PR branch has to contain main.".into(),
            score: 1.0,
            kind: "lesson".into(),
            ts: None,
            entities: vec![],
            ballots: None,
            of: None,
        };
        assert!(!is_refresher(&untagged));
    }

