    #[test]
    fn a_dangling_deed_is_refused() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("deedar");
        publish_exe(
            &bin,
            "#!/bin/sh\ncase \"$2\" in\nknown) exit 0;;\n*) echo \"no such deed $2\" >&2; exit 1;;\nesac\n",
        );
        let path = std::env::var("PATH").unwrap_or_default();
        let _env = HoldEnv::set(&[("PATH", &format!("{}:{}", dir.path().display(), path))]);
        let err = super::require_deed("deed-missing").unwrap_err().to_string();
        assert!(err.contains("deed-missing"), "{err}");
        assert!(err.contains("not in the deed store"), "{err}");
        assert!(super::require_deed("known").is_ok());
        assert!(super::require_deed("  ").is_err());
    }

    /// A citation takes what `deedar create` prints: the accession line,
    /// the id line, the whole output, or the product digest line.
    #[test]
    fn a_deed_citation_takes_what_create_prints() {
        let hex = "ab".repeat(32);
        let created = format!(
            "id=deed-file-survey kind=file name=survey\npaths=sha256:{hex}\nfile=sha256:{hex}\naccession=deed-file-survey\n"
        );
        for raw in [
            "deed-file-survey".to_string(),
            "accession=deed-file-survey".to_string(),
            "id=deed-file-survey kind=file name=survey".to_string(),
            created,
        ] {
            assert_eq!(super::deed_token(&raw), "deed-file-survey", "{raw}");
        }
        assert_eq!(
            super::deed_token(&format!("file=sha256:{hex}")),
            format!("sha256:{hex}")
        );
        assert_eq!(super::deed_token("  "), "");
    }

    /// A digest names its deed; the cite carries the deed's own id.
    #[test]
    fn a_digest_citation_resolves_to_the_deed_id() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("deedar");
        publish_exe(
            &bin,
            "#!/bin/sh\ncase \"$2\" in\nsha256:*) echo 'id=deed-file-survey kind=file name=survey'; echo 'accession=deed-file-survey';;\ndeed-file-survey) echo 'id=deed-file-survey kind=file';;\n*) echo \"invalid deed id: $2\" >&2; exit 1;;\nesac\n",
        );
        let path = std::env::var("PATH").unwrap_or_default();
        let _env = HoldEnv::set(&[("PATH", &format!("{}:{}", dir.path().display(), path))]);
        let digest = format!("file=sha256:{}", "cd".repeat(32));
        assert_eq!(super::resolve_deed(&digest).unwrap(), "deed-file-survey");
        assert_eq!(
            super::resolve_deed("accession=deed-file-survey").unwrap(),
            "deed-file-survey"
        );
        assert!(super::resolve_deed("nonsense").is_err());
    }

    /// A refusal from the command check says what the command would do
    /// and what to run instead, and keeps the check's token first.
    #[test]
    fn a_policyd_refusal_reads_as_words_with_its_token_first() {
        for token in [
            "git-force-push",
            "git-reset-hard",
            "git-clean-force",
            "git-stash-clear",
            "git-discard-worktree",
            "rm-rf-outside-tmp",
            "find-delete-outside-tmp",
            "curl-pipe-shell",
            "raw-disk",
            "chmod-setuid",
            "sudo",
            "secret-in-argv",
            "shell-secret-in-argv",
            "python-missing-pep723",
            "path-outside-workspace",
            "python-dash-c",
            "python-requires-uv",
        ] {
            let said = policyd_reason(token);
            assert!(said.starts_with(&format!("{token}: ")), "{said}");
            assert!(said.len() > token.len() + 40, "{said}");
        }
        // One short sentence that fits a terminal line and recommends no
        // other push: a lease push asks too onto main, master or develop.
        let force = policyd_reason("git-force-push");
        assert!(force.len() < 100, "{} columns: {force}", force.len());
        assert!(!force.contains("--force-with-lease"), "{force}");
        assert_eq!(force.matches(". ").count(), 0, "{force}");
        assert!(policyd_reason("git-reset-hard").contains("git stash"));
        let secret = policyd_reason("shell-secret-in-argv: token on the command line");
        assert!(secret.starts_with("shell-secret-in-argv: "), "{secret}");
        assert!(secret.contains("shell history"), "{secret}");
        assert!(secret.contains("token on the command line"), "{secret}");
        let path = policyd_reason("path-outside-workspace: /etc/passwd");
        assert!(path.contains("outside the workspace"), "{path}");
        assert!(path.contains("/etc/passwd"), "{path}");
        let python = policyd_reason("python-missing-pep723");
        assert!(python.contains("PEP 723"), "{python}");
        assert_eq!(policyd_reason("a-token-from-later"), "a-token-from-later");
        assert_eq!(policyd_reason(" phronesis "), "phronesis");
        let identity = policyd_reason("git-commit-identity");
        assert!(identity.contains(".ljos/gates.toml"), "{identity}");
        assert!(identity.contains("ljos.toml"), "{identity}");
        assert!(!identity.contains("git config"), "{identity}");
        assert!(!identity.contains("user.name"), "{identity}");
        assert!(!identity.contains("GIT_AUTHOR"), "{identity}");
        assert!(!identity.contains("GIT_COMMITTER"), "{identity}");
    }

    /// Every command a guard reason recommends is allowed by that same gate.
    /// The force-push reason recommends no command. `--force` asks, and so
    /// does `--force-with-lease` onto main; onto a feature branch it runs.
    #[test]
    fn recommended_commands_are_not_refused_by_the_same_gate() {
        let mut reasons = Vec::new();
        for token in [
            "git-force-push",
            "git-reset-hard",
            "git-clean-force",
            "git-stash-clear",
            "git-discard-worktree",
            "rm-rf-outside-tmp",
            "find-delete-outside-tmp",
            "curl-pipe-shell",
            "raw-disk",
            "chmod-setuid",
            "sudo",
            "secret-in-argv",
            "shell-secret-in-argv",
            "python-missing-pep723",
            "path-outside-workspace",
            "python-dash-c",
            "python-requires-uv",
            "git-commit-identity",
            "git-commit-message",
            "git-commit-trailer",
            "git-commit-signoff",
            "git-push-evidence",
            "git-merge-unready",
            "git-remote-hidden",
        ] {
            reasons.push(policyd_reason(token));
        }
        reasons.extend(ask_pack::pack_reasons());
        let mut commands = Vec::new();
        for reason in &reasons {
            let mut rest = reason.as_str();
            while let Some(start) = rest.find('`') {
                let after = &rest[start + 1..];
                let Some(end) = after.find('`') else {
                    break;
                };
                let span = after[..end].trim();
                rest = &after[end + 1..];
                let Some(first) = span.split_whitespace().next() else {
                    continue;
                };
                if first.starts_with(|c: char| c.is_ascii_alphabetic())
                    && !first.contains(['=', ':'])
                {
                    commands.push(span.to_string());
                }
            }
        }
        assert!(
            !commands
                .iter()
                .any(|line| line.contains("--force-with-lease")),
            "a lease push asks, so no reason recommends it: {commands:?}"
        );
        let repo = tempfile::tempdir().unwrap();
        let home = tempfile::tempdir().unwrap();
        let data = tempfile::tempdir().unwrap();
        let git = |args: &[&str]| {
            let out = std::process::Command::new("git")
                .arg("-C")
                .arg(repo.path())
                .args(args)
                .output()
                .unwrap();
            assert!(
                out.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&out.stderr)
            );
        };
        git(&["init", "-q"]);
        git(&["config", "user.email", "seat@example.invalid"]);
        git(&["config", "user.name", "seat"]);
        git(&["config", "commit.gpgsign", "false"]);
        git(&["config", "core.hooksPath", "/dev/null"]);
        git(&["branch", "-M", "main"]);
        std::fs::write(repo.path().join("README.md"), "seed\n").unwrap();
        std::fs::write(repo.path().join("note.txt"), "land the note\n").unwrap();
        git(&["add", "README.md"]);
        git(&["commit", "-q", "-m", "seed"]);
        let _g = env_guard();
        let _env = HoldEnv::set(&[
            ("XDG_DATA_HOME", data.path().to_str().unwrap()),
            ("LJOS_CONFIG", ""),
            ("LJOS_OFF", "0"),
        ]);
        super::with_config_home(home.path(), || {
            let mut seen = std::collections::BTreeSet::new();
            for template in &commands {
                let line = template
                    .replace("<test command>", "true")
                    .replace("stash@{N}", "stash@{0}")
                    .split_whitespace()
                    .map(|word| match word {
                        "FILE" => "note.txt",
                        "TEXT" => "land",
                        "REF" => "HEAD",
                        other => other,
                    })
                    .collect::<Vec<_>>()
                    .join(" ");
                if !seen.insert(line.clone()) {
                    continue;
                }
                let ruled = gates::guard_verdict(&line, Some(repo.path()), &[]);
                assert!(
                    ruled.is_none(),
                    "recommended `{line}` (from `{template}`) is refused: {ruled:?}"
                );
            }
            let lease = guard_line("git push --force-with-lease origin HEAD:main", repo.path())
                .expect("a lease push asks");
            assert_eq!(lease.verdict, "ask");
            assert_eq!(lease.pattern, "git-force-push");
            let includes = guard_line("git push --force-if-includes origin HEAD:main", repo.path());
            assert!(includes.is_none(), "{includes:?}");
            let leased = guard_line(
                "git push --force-with-lease=refs/heads/main origin main",
                repo.path(),
            )
            .expect("a lease push with a ref asks");
            assert_eq!(leased.verdict, "ask");
            let upstream = guard_line("git push -u origin feature", repo.path());
            assert!(upstream.is_none(), "{upstream:?}");
            let forced = guard_line("git push --force origin HEAD:main", repo.path())
                .expect("a force push still asks");
            assert_eq!(forced.verdict, "ask");
            assert_eq!(forced.pattern, "git-force-push");
            assert!(
                forced.reason.contains("asks you first"),
                "{}",
                forced.reason
            );
            let both = guard_line(
                "git push --force-with-lease --force origin HEAD:main",
                repo.path(),
            )
            .expect("lease plus --force still asks");
            assert_eq!(both.verdict, "ask");
            let plus = guard_line("git push origin +main", repo.path()).expect("+refspec asks");
            assert_eq!(plus.verdict, "ask");
        });
    }

    fn guard_line(line: &str, cwd: &std::path::Path) -> Option<super::Rule> {
        gates::guard_verdict(line, Some(cwd), &[])
    }

    /// The hook's verdict carries those words, and the runner is asked.
    #[test]
    fn the_hook_explains_a_force_push_refusal_in_words() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("ljos-policyd");
        std::fs::write(
            &bin,
            "#!/bin/sh\ncase \"$*\" in\n*--force*) printf 'deny\\tgit-force-push\\n'; exit 2;;\n*) printf 'allow\\n';;\nesac\n",
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
        let home = SeatDir::new("force-push-hook");
        let _env = HoldEnv::set(&[
            ("POLICYD_BIN", bin.to_str().unwrap()),
            ("HOME", home.path().to_str().unwrap()),
        ]);
        assert!(tcb_verdict("git status").is_none());
        let unrecorded = tcb_verdict("git push --force origin main").expect("a force push asks");
        assert_eq!(unrecorded.verdict, "ask");
        assert!(
            !unrecorded.reason.contains("git-push-evidence"),
            "{}",
            unrecorded.reason
        );
        let repo = evidenced_push_repo();
        let rule =
            static_guard_in("git push --force origin main", Some(repo.path())).expect("asks");
        assert_eq!(rule.verdict, "ask");
        assert_eq!(rule.pattern, "git-force-push");
        assert!(
            rule.reason.starts_with("git-force-push: "),
            "{}",
            rule.reason
        );
        let call = HookCall {
            event: "PreToolUse".into(),
            cue: "git push --force origin main".into(),
            session: None,
            shape: HookShape::CamelCase,
        };
        let answer = hook_output_ruled(&call, "", Some(&rule));
        assert!(!answer_denies(&answer), "{answer}");
        assert!(
            answer.contains("\"permissionDecision\":\"ask\""),
            "{answer}"
        );
        assert!(answer.contains("asks you first"), "{answer}");
        assert!(!answer.contains("--force-with-lease"), "{answer}");
        let codex = HookCall {
            event: "PreToolUse".into(),
            cue: "git push --force origin main".into(),
            session: Some("codex-1".into()),
            shape: HookShape::DenyOnly,
        };
        // Codex does not honour `ask`: the same force push is a deny.
        // A bare ask, with no grant written yet, says the runner cannot
        // ask. A reason that already offers `ljos approve` keeps that
        // offer and does not tell the agent the refusal never lifts.
        let codex_answer = hook_output_ruled(&codex, "", Some(&rule));
        assert!(
            codex_answer.contains("\"permissionDecision\":\"deny\""),
            "{codex_answer}"
        );
        assert!(
            !codex_answer.contains("\"permissionDecision\":\"ask\""),
            "{codex_answer}"
        );
        assert!(
            codex_answer.contains("ask the person before running this"),
            "{codex_answer}"
        );
        // Codex shows no prompt, so its reason does not promise one.
        assert!(!codex_answer.contains("asks you first"), "{codex_answer}");
        assert!(
            codex_answer.contains("needs the person's approval"),
            "{codex_answer}"
        );
        let mut offered = rule.clone();
        offered.reason.push_str(
            " Reply `approve oak-abcdef` in this conversation, call the ljos_request_approval \
             MCP tool with id oak-abcdef, or run `ljos approve oak-abcdef`.",
        );
        let offered_answer = hook_output_ruled(&codex, "", Some(&offered));
        assert!(
            offered_answer.contains("\"permissionDecision\":\"deny\""),
            "{offered_answer}"
        );
        assert!(
            offered_answer.contains("ljos approve oak-abcdef"),
            "{offered_answer}"
        );
        assert!(
            !offered_answer.contains("leave it for them"),
            "{offered_answer}"
        );
        assert!(
            !offered_answer.contains("asks you first"),
            "{offered_answer}"
        );
        let cursor = HookCall {
            event: "PreToolUse".into(),
            cue: "git push --force origin main".into(),
            session: Some("cursor-1".into()),
            shape: HookShape::Cursor,
        };
        let cursor_answer = hook_output_ruled(&cursor, "", Some(&offered));
        assert!(
            cursor_answer.contains("\"permission\":\"deny\""),
            "{cursor_answer}"
        );
        assert!(
            !cursor_answer.contains("\"permission\":\"ask\""),
            "{cursor_answer}"
        );
        assert!(
            cursor_answer.contains("ljos approve oak-abcdef"),
            "{cursor_answer}"
        );
        assert!(
            !cursor_answer.contains("leave it for them"),
            "{cursor_answer}"
        );
        let bare_cursor = hook_output_ruled(&cursor, "", Some(&rule));
        assert!(bare_cursor.contains("cannot ask here"), "{bare_cursor}");
    }

    /// `ljos_guard_check` asks about a force push, with or without test
    /// evidence. `guard_command` reports the ask as an error. `git status`
    /// stays allowed.
    #[test]
    fn a_force_push_asks_whether_or_not_it_has_evidence() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("ljos-policyd");
        std::fs::write(
            &bin,
            "#!/bin/sh\ncase \"$*\" in\n*--force*) printf 'deny\\tgit-force-push\\n'; exit 2;;\n*) printf 'allow\\n';;\nesac\n",
        )
        .unwrap();
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&bin, std::fs::Permissions::from_mode(0o755)).unwrap();
        let home = SeatDir::new("force-push-check");
        let _env = HoldEnv::set(&[
            ("POLICYD_BIN", bin.to_str().unwrap()),
            ("HOME", home.path().to_str().unwrap()),
        ]);
        let report = guard_report("git push --force origin main").expect("an ask is a report");
        assert_eq!(report.verdict, "ask", "{}", report.text);
        assert!(
            !report.text.contains("git-push-evidence"),
            "{}",
            report.text
        );
        let err = guard_command("git push --force origin main")
            .unwrap_err()
            .to_string();
        assert!(err.contains("git-force-push"), "{err}");
        let allowed = guard_report("git status").expect("status is allowed");
        assert_eq!(allowed.verdict, "allow");
        let repo = evidenced_push_repo();
        let asked =
            static_guard_in("git push --force origin main", Some(repo.path())).expect("ask");
        assert_eq!(asked.verdict, "ask");
        assert!(asked.reason.contains("git-force-push"), "{}", asked.reason);
    }

    fn habitat_row(name: &'static str, state: &str, ok: bool) -> Habitat {
        Habitat {
            name,
            state: state.to_string(),
            ok,
        }
    }

    #[test]
    fn a_ready_doctor_is_one_line() {
        let rows = vec![
            habitat_row("pack", "answers", true),
            habitat_row("tracker", "answers", true),
            habitat_row("policy", "ljos-policyd 0.4.6 (phronesis)", true),
            habitat_row("host key", "none yet", false),
        ];
        let short = format_doctor_short(&rows);
        assert_eq!(
            short,
            "ljos is ready: memory, tracker and command guard work. Optional extras: `ljos doctor --all`.\n"
        );
        assert!(format_doctor(&rows).contains("host key"));
    }

    #[test]
    fn a_ready_line_names_only_the_parts_that_work() {
        let tracker = habitat_row(
            "tracker",
            "`vissue identity` exited 1: not inside a tracker",
            false,
        );
        let mut rows = vec![
            habitat_row("pack", "answers", true),
            tracker.clone(),
            habitat_row("policy", "ljos-policyd 0.4.6 (phronesis)", true),
            habitat_row("host key", "none yet", false),
            habitat_row("cloud guard", "missing; run `ljos cloud up`", false),
        ];
        assert!(healthy(&rows));
        assert_eq!(
            format_doctor_short(&rows),
            "ljos is ready: memory and command guard work. Optional extras: `ljos doctor --all`.\n\
             info\ttracker\t`vissue identity` exited 1: not inside a tracker\n"
        );
        rows.push(habitat_row("guard", "off: LJOS_OFF is set", false));
        let short = format_doctor_short(&rows);
        assert!(
            short.starts_with("ljos is ready: memory works. Optional extras"),
            "{short}"
        );
        assert!(
            short.contains("warn\tguard\toff: LJOS_OFF is set\n"),
            "{short}"
        );

        // A sitting's report cuts its doctor section to the same line.
        let full = format!(
            "== doctor\n{}",
            format_doctor(&[
                habitat_row("ljos-policyd", "/bin/ljos-policyd  0.4.6", true),
                habitat_row("pack", "answers", true),
                tracker,
            ])
        );
        let sat = compact_sitting(&full, "Software-x");
        assert!(
            sat.starts_with(
                "ljos is ready: memory and command guard work. Optional extras: `ljos doctor --all`.\n\
                 info\ttracker\t`vissue identity` exited 1: not inside a tracker\n"
            ),
            "{sat}"
        );
    }

    #[test]
    fn a_short_doctor_names_what_is_down_with_its_fix() {
        let rows = vec![
            habitat_row("pack", "no pack: run packset ensure", false),
            habitat_row(
                "encoder",
                "not installed: cargo binstall packset-embed",
                false,
            ),
            habitat_row("tracker", "answers", true),
        ];
        let short = format_doctor_short(&rows);
        let lines: Vec<&str> = short.lines().collect();
        // The encoder is optional, so a missing one is an info row, not a
        // reason the seat is not ready. The short doctor still names the
        // pack, with its fix.
        assert_eq!(
            lines[0],
            "ljos is not ready: memory does not answer. Optional extras: `ljos doctor --all`."
        );
        assert_eq!(lines.len(), 2, "{short}");
        assert!(lines[1].starts_with("no\tpack\tno pack: run packset ensure"));
        assert!(!short.contains("tracker"), "{short}");
        assert!(!short.contains("encoder"), "{short}");
        assert!(format_doctor(&rows).contains("info\tencoder\t"));
    }

