    /// A removal is an appended ledger event. The heading that already
    /// cited the deed stays byte for byte, and the folded list drops it.
    #[test]
    fn removing_a_citation_appends_the_event_and_leaves_the_heading() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let project = root.join("Software/probe");
        std::fs::create_dir_all(project.join("issues")).unwrap();
        std::fs::write(
            project.join("issues.org"),
            "#+TITLE: probe issues\n#+VISSUE: 1\n#+TODO: TODO STARTED | DONE\n",
        )
        .unwrap();
        std::fs::write(project.join("issues/.ledger"), "1\nabc\n").unwrap();
        let ledger = "\
#+TITLE: probe issues
#+VISSUE: 1
#+TODO: TODO STARTED | DONE

#+VISSUE_LEDGER:
#+VISSUE_LINES: 6 11
* TODO [#C] Cited
:PROPERTIES:
:ID:         probe-c1te
:DEEDS:      deed-file deed-keep
:END:
#+VISSUE_LEDGER_LOG:
";
        let issue_file = project.join("issues/probe-c1te.org");
        std::fs::write(&issue_file, ledger).unwrap();
        let root_s = root.to_str().unwrap();
        unsafe { std::env::remove_var("ISSUE_ROOT") };
        let _env = HoldEnv::set(&[
            ("VISSUE_ROOT", root_s),
            ("VISSUE_NO_ROUTE", "1"),
            ("LJOS_TRACKER_GIT", "off"),
        ]);

        let before = std::fs::read(&issue_file).unwrap();
        let mark = before
            .windows(b"#+VISSUE_LEDGER_LOG:".len())
            .position(|w| w == b"#+VISSUE_LEDGER_LOG:")
            .expect("ledger mark");
        let said = super::uncite_deed("probe-c1te", "deed-file").unwrap();
        assert!(said.contains("deeds -= deed-file"), "{said}");
        let after = std::fs::read(&issue_file).unwrap();
        assert_eq!(&after[..mark], &before[..mark], "the heading was rewritten");
        assert!(after.len() > before.len(), "nothing was appended");
        let text = String::from_utf8(after).unwrap();
        assert!(text.contains("removed citation deed-file"), "{text}");
        assert!(text.contains(":DEEDS:      deed-file deed-keep"), "{text}");
        let card = super::tracker_show_json("probe-c1te").unwrap();
        let left: Vec<&str> = card["deeds"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        assert_eq!(left, vec!["deed-keep"]);
        let again = super::uncite_deed("probe-c1te", "deed-file")
            .unwrap_err()
            .to_string();
        assert!(again.contains("does not cite"), "{again}");
        assert!(again.contains("deed-file"), "{again}");
        assert!(super::uncite_deed("probe-c1te", "  ").is_err());
    }

    /// A freshly filed issue sits on a board. Removing a citation splits
    /// the board into a ledger first, then appends the removal, so a
    /// superseded deed can be dropped the minute the issue exists.
    #[test]
    fn removing_a_citation_from_a_board_splits_it_first() {
        let _g = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let root = dir.path();
        let project = root.join("Software/probe");
        std::fs::create_dir_all(&project).unwrap();
        let board = "\
#+TITLE: probe issues
#+VISSUE: 1
#+TODO: TODO STARTED | DONE
* TODO [#C] Board
:PROPERTIES:
:ID:         probe-b0rd
:DEEDS:      deed-file deed-keep
:END:
";
        let issues = project.join("issues.org");
        std::fs::write(&issues, board).unwrap();
        let root_s = root.to_str().unwrap();
        unsafe { std::env::remove_var("ISSUE_ROOT") };
        let _env = HoldEnv::set(&[
            ("VISSUE_ROOT", root_s),
            ("VISSUE_NO_ROUTE", "1"),
            ("LJOS_TRACKER_GIT", "off"),
        ]);
        let said = super::uncite_deed("probe-b0rd", "deed-file")
            .unwrap_or_else(|e| panic!("removal on a board failed: {e:#}"));
        assert!(said.contains("split the board into a ledger"), "{said}");
        assert_eq!(
            std::fs::read_to_string(&issues).unwrap(),
            board,
            "the board was rewritten"
        );
        assert!(project.join("issues/probe-b0rd.org").is_file());
        let card = super::tracker_show_json("probe-b0rd").unwrap();
        let left: Vec<&str> = card["deeds"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(|v| v.as_str())
            .collect();
        assert_eq!(left, vec!["deed-keep"]);
    }

    /// No coding tool is not an empty seat: the tracker and the other
    /// stores are still prepared, or doctor names a tracker that is not there.
    #[test]
    fn a_seat_with_no_runner_still_gets_its_tracker() {
        let _g = env_guard();
        let _seat = HermeticSeat::new();
        let empty = tempfile::tempdir().unwrap();
        // SAFETY: env_guard restores PATH with the rest of the environment.
        unsafe { std::env::set_var("PATH", empty.path()) };
        let steps = super::onboard_detected(true, None).expect("dry onboard");
        let whats: Vec<&str> = steps.iter().map(|s| s.what.as_str()).collect();
        assert!(
            steps[0].detail.contains("found no coding tool"),
            "{steps:?}"
        );
        for need in ["deed store", "tracker", "pack", "host key"] {
            assert!(whats.contains(&need), "{whats:?}");
        }
        assert!(steps.iter().all(|s| s.ok), "{steps:?}");
        let tracker = steps.iter().find(|s| s.what == "tracker").unwrap();
        assert!(
            tracker.detail.starts_with("would create"),
            "{}",
            tracker.detail
        );
    }

    /// A non-zero exit is an error carrying what was said on stderr.
    #[test]
    fn a_refusal_is_an_error_not_an_answer() {
        let _env = env_guard();
        let err = run_captured("false", &[] as &[&str]).unwrap_err();
        assert_eq!(err.to_string(), "false failed (exit 1)");
        let said = run_captured("sh", &["-c", "echo answered; echo aside >&2"]).unwrap();
        assert_eq!(said.stdout.trim(), "answered");
        assert_eq!(said.stderr.trim(), "aside");
        let said =
            run_captured("sh", &["-c", "echo 'sh: the store is missing' >&2; exit 1"]).unwrap_err();
        assert_eq!(said.to_string(), "sh failed (exit 1): the store is missing");
        let said = run_captured(
            "sh",
            &["-c", "echo 'vissue: /tmp/x is not a tracker' >&2; exit 1"],
        )
        .unwrap_err();
        assert_eq!(
            said.to_string(),
            "sh failed (exit 1): vissue: /tmp/x is not a tracker"
        );
        assert!(!said.to_string().contains("exit status"), "{said}");
    }

    /// A habitat that never exits used to hold the caller. The capture
    /// stops it and says so.
    #[test]
    fn run_captured_stops_when_the_command_does_not_answer() {
        let _g = env_guard();
        let started = std::time::Instant::now();
        let err = run_captured_within(
            "sh",
            &["-c", "exec sleep 30"],
            None,
            std::time::Duration::from_millis(400),
        )
        .unwrap_err();
        assert!(
            started.elapsed() < std::time::Duration::from_secs(3),
            "waited {:?}",
            started.elapsed()
        );
        assert!(err.to_string().contains("did not answer in time"), "{err}");
    }

