    #[test]
    fn atom_body_is_explicit_and_unextracted() {
        let v = atom_body("lesson", "the default fuse is CombMNZ", "ws");
        assert_eq!(v["schema"], "inside.atom/v1");
        assert_eq!(v["kind"], "lesson");
        assert_eq!(v["level"], "explicit");
        assert_eq!(v["text"], "the default fuse is CombMNZ");
        assert_eq!(v["workspace"], "ws");
        // Every write says where it came from.
        assert_eq!(v["source"]["via"], "ljos");
        assert!(!v["source"]["host"].as_str().unwrap_or("").is_empty());
        assert!(!v["source"]["session"].as_str().unwrap_or("").is_empty());
        // Every write names the seat that wrote it, and other entities join it.
        let seat = v["entities"][0].as_str().unwrap();
        assert!(seat.starts_with(SEAT_ENTITY), "{seat}");
        let mut more = v.clone();
        add_entities(
            &mut more,
            ["persona:reviewer".to_string(), seat.to_string()],
        );
        assert_eq!(more["entities"].as_array().unwrap().len(), 2, "{more}");
        // Never harvest a transcript: the text is the claim, not a prefix parse.
        let raw = atom_body("lesson", "Remember: pin the review set", "ws");
        assert_eq!(raw["text"], "Remember: pin the review set");
    }

    #[test]
    fn lessons_for_two_issues_both_stay_open() {
        // The two lessons a real pair of sittings wrote. Ten of the sixteen
        // words are shared, past the pack's rewrite threshold.
        let first = "git function slugify slug lowercases (work-1jvz) closed. Import slug; slug.slugify(\"hello world\") failed.";
        let second = "git function kebab case slug reuses (work-fyv7) closed. Import slug; slug.slugify('hello world') failed.";
        let lesson = |text: &str, issue: &str| {
            agent_sourced_atom("Remember", text, "ws", Some(false), "", "", "", issue).unwrap()
        };
        let a = lesson(first, "work-1jvz");
        let b = lesson(second, "work-fyv7");
        assert_eq!(a["issue"], "work-1jvz");
        assert_eq!(b["issue"], "work-fyv7");
        assert_eq!(a["text"], first);
        assert_eq!(b["text"], second);
        let a = a.as_object().unwrap();
        let b = b.as_object().unwrap();
        let shape = packset_core::record::Shape::of;
        assert!(
            !packset_core::record::replaces_shaped(b, &shape(b), a, &shape(a)),
            "a later issue's lesson closed the earlier one"
        );
        assert!(!packset_core::record::replaces_shaped(
            a,
            &shape(a),
            b,
            &shape(b)
        ));
        // The texts alone are one claim. The issue field is what keeps them apart.
        let mut bare_a = a.clone();
        let mut bare_b = b.clone();
        bare_a.remove("issue");
        bare_b.remove("issue");
        assert!(
            packset_core::record::replaces_shaped(
                &bare_b,
                &shape(&bare_b),
                &bare_a,
                &shape(&bare_a)
            ),
            "these two texts are in the rewrite band"
        );
        let revised = "git function slugify slug lowercases (work-1jvz) closed. Import slug; slug.slugify(\"hello world\") failed again.";
        let next = lesson(revised, "work-1jvz");
        let next = next.as_object().unwrap();
        assert!(
            packset_core::record::replaces_shaped(next, &shape(next), a, &shape(a)),
            "a revision of the same issue's lesson still replaces it"
        );
        assert!(!packset_core::record::replaces_shaped(
            next,
            &shape(next),
            b,
            &shape(b)
        ));
        let unclaimed = lesson(first, "  ");
        assert!(unclaimed.get("issue").is_none());
    }

    #[test]
    fn a_short_id_names_the_one_id_it_starts() {
        let ids = vec![
            "922d35cd0123456789abcdef01234567".to_string(),
            "922d35ff0123456789abcdef01234567".to_string(),
            "a1b2c3d40123456789abcdef01234567".to_string(),
        ];
        assert_eq!(
            resolve_short_id("forget", "a1b2c3d4", &ids).unwrap(),
            ids[2]
        );
        assert_eq!(
            resolve_short_id("forget", "922d35cd", &ids).unwrap(),
            ids[0]
        );
        let err = resolve_short_id("forget", "922d35", &ids)
            .unwrap_err()
            .to_string();
        assert!(err.contains("starts 2 ids"), "{err}");
        // Too short, unknown, or whole: taken as typed.
        assert_eq!(resolve_short_id("forget", "922", &ids).unwrap(), "922");
        assert_eq!(
            resolve_short_id("forget", "ffffffff", &ids).unwrap(),
            "ffffffff"
        );
        assert_eq!(resolve_short_id("forget", &ids[1], &ids).unwrap(), ids[1]);
    }

    #[test]
    fn a_person_sees_the_ack_in_local_time_with_a_short_id() {
        let zone = chrono::FixedOffset::west_opt(5 * 3600).unwrap();
        assert_eq!(
            local_when_in("2026-10-12T14:00:00Z", &zone),
            "2026-10-12 09:00 -05:00"
        );
        assert_eq!(local_when_in("not a time", &zone), "not a time");
        let body = serde_json::json!({
            "id": "922d35cd0123456789abcdef01234567",
            "kind": "preference",
            "text": "Plain words in denials.",
            "due_at": "2026-10-12T14:00:00Z",
        });
        let when = |d: &str| local_when_in(d, &zone);
        assert_eq!(
            format_write_ack_plain(&body, &when),
            "remembered (preference): Plain words in denials.\n  id 922d35cd, next review 2026-10-12 09:00 -05:00"
        );
        // A pipe keeps the tab row.
        assert!(
            format_write_ack(&body).starts_with("922d35cd0123456789abcdef01234567\tpreference\t")
        );
        let rule = serde_json::json!({
            "id": "e58887670123456789abcdef01234567",
            "kind": "rule",
            "text": "Destroy only from the release runbook.",
            "pattern": "terraform destroy*",
            "verdict": "deny",
            "due_at": "2026-10-12T14:00:00Z",
        });
        assert_eq!(
            format_write_ack_plain(&rule, &when),
            "rule deny `terraform destroy*`: Destroy only from the release runbook.\n  id e5888767, next review 2026-10-12 09:00 -05:00"
        );
    }

