    #[test]
    fn a_panel_seats_who_speaks_to_the_title_not_the_island_s_neighbours() {
        let mk = |name: &str, about: &[&str], view: &str| Persona {
            name: name.into(),
            anchor: 0.3,
            view: view.into(),
            entities: about.iter().map(|s| s.to_string()).collect(),
            runner: None,
        };
        let all = vec![
            mk(
                "numericschem",
                &["neb", "numerics"],
                "Reads for changes that pass the tests and give wrong physics.",
            ),
            mk(
                "glassphysicist",
                &["glass", "diffuse"],
                "Studies two-level systems in glasses.",
            ),
            mk(
                "secreviewer",
                &["capabilities", "security"],
                "Treats any capability kept past startup as attack surface.",
            ),
        ];
        let title = "decision :: post the cvmfs passthrough PR, and with which capability change";
        let direct: Vec<String> = [
            "decision",
            "post",
            "cvmfs",
            "passthrough",
            "capability",
            "change",
        ]
        .iter()
        .map(|s| s.to_string())
        .collect();
        let island: Vec<String> = ["diffuse", "numerics", "capabilities"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        let seated: Vec<String> = seat_panel(&all, &direct, &island, title)
            .into_iter()
            .map(|p| p.name)
            .collect();
        assert_eq!(
            seated,
            ["secreviewer"],
            "the island seats only who also speaks to the title"
        );
        let none = seat_panel(&all[..2], &direct, &island, title);
        assert!(
            none.is_empty(),
            "nobody is a correct answer: {:?}",
            none.iter().map(|p| &p.name).collect::<Vec<_>>()
        );
        let direct_hit = seat_panel(&all, &["neb".to_string()], &[], "neb tolerance");
        assert_eq!(direct_hit[0].name, "numericschem");
    }

    #[test]
    fn a_persona_votes_through_the_seat_under_its_own_name() {
        let _g = env_guard();
        // The runners file is this test's own, not the machine's: a
        // persona's runner must be a [[harness]] there.
        let config = tempfile::tempdir().unwrap();
        std::fs::create_dir_all(config.path().join("ljos")).unwrap();
        std::fs::write(
            config.path().join("ljos/harnesses.toml"),
            "[[harness]]\nname = \"grok\"\n\n[[harness]]\nname = \"shell\"\nshell = true\n",
        )
        .unwrap();
        let saved = std::env::var_os("XDG_CONFIG_HOME");
        // SAFETY: the lock above is the only environment this test touches.
        unsafe { std::env::set_var("XDG_CONFIG_HOME", config.path()) };
        let task = persona_ballot_task("BRIEF", "buildengineer", "surf-ab12");
        assert!(task.starts_with("BRIEF"));
        assert!(
            task.contains("ljos vote surf-ab12 --for OPTION --expect OPTION --as buildengineer ")
        );
        assert!(task.contains("ljos note"));
        assert!(!task.contains("ljos remember"));
        assert!(task.contains("Do not open a sitting"));
        let p = Persona {
            name: "buildengineer".into(),
            anchor: 0.25,
            view: "Reads pipelines.".into(),
            entities: vec!["jenkins".into()],
            runner: Some("grok".into()),
        };
        let atom = persona_atom(&p, "seat").unwrap();
        assert_eq!(atom["runner"], "grok");
        let mut back = personas_of(&[serde_json::json!({
            "kind": "persona", "name": "buildengineer", "anchor": 0.25,
            "text": "Reads pipelines.", "runner": "grok", "ts": "2026-10-02T00:00:00Z"
        })]);
        assert_eq!(back.pop().unwrap().runner.as_deref(), Some("grok"));
        // A runner the file does not name is refused, and says which it names.
        let stray = Persona {
            runner: Some("nowhere".into()),
            ..p
        };
        let err = persona_atom(&stray, "seat").unwrap_err().to_string();
        assert!(err.contains("grok, shell"), "{err}");
        // SAFETY: as above.
        unsafe {
            match saved {
                Some(v) => std::env::set_var("XDG_CONFIG_HOME", v),
                None => std::env::remove_var("XDG_CONFIG_HOME"),
            }
        }
    }

    #[test]
    fn persona_ballots_neither_pass_nor_block_a_push_cite() {
        let personas: std::collections::BTreeSet<String> =
            ["reviewer".to_string(), "reader".to_string()].into();
        let ballot =
            |agent: &str, choice: &str| serde_json::json!({"agent": agent, "choice": choice});
        // Personas and a judge alone: nothing counted, so nothing stands.
        let only = [
            ballot("reviewer", "ship"),
            ballot("reader", "ship"),
            ballot("judge:grok-4", "ship"),
        ];
        let err = seats_decide("surf-ab12", &only, &personas, "grok").unwrap_err();
        assert_eq!(
            err,
            "no seat voted on surf-ab12, so it decides nothing for a push; \
             3 persona and judge ballots left out; a seat votes, or the person approves this push"
        );
        // One seat for ship against every persona for hold: the personas
        // do not block it. Before, the settle over all ballots named hold
        // and the seat was refused.
        let outvoted = [
            ballot("codex", "ship"),
            ballot("reviewer", "hold"),
            ballot("reader", "hold"),
            ballot("judge:grok-4", "hold"),
        ];
        let d = seats_decide("surf-ab12", &outvoted, &personas, "grok").unwrap();
        assert_eq!(d.choice, "ship");
        assert_eq!(
            d.counted,
            "codex for ship; 3 persona and judge ballots left out"
        );
        // Seats that split decide nothing, and the refusal names them.
        let mut split = outvoted.to_vec();
        split.push(ballot("rgoswami", "hold"));
        let err = seats_decide("surf-ab12", &split, &personas, "grok").unwrap_err();
        assert_eq!(
            err,
            "the seats on surf-ab12 split, so it decides nothing for a push: \
             counted codex for ship, rgoswami for hold; 3 persona and judge ballots left out"
        );
        // No advice on the ballot: nothing said about it.
        let plain = [ballot("codex", "ship")];
        assert_eq!(
            seats_decide("surf-ab12", &plain, &personas, "grok")
                .unwrap()
                .counted,
            "codex for ship"
        );
    }

    #[test]
    fn the_pushing_seat_does_not_back_its_own_cite() {
        let personas: std::collections::BTreeSet<String> = ["reviewer".to_string()].into();
        let ballot =
            |agent: &str, choice: &str| serde_json::json!({"agent": agent, "choice": choice});
        let own = [ballot("grok", "ship"), ballot("reviewer", "ship")];
        let err = seats_decide("surf-ab12", &own, &personas, "grok").unwrap_err();
        assert_eq!(
            err,
            "the only seat ballot on surf-ab12 is from grok, the seat pushing: \
             counted grok for ship; 1 persona or judge ballot left out; \
             another seat votes ship, or the person approves this push"
        );
        let mut seen = own.to_vec();
        seen.push(ballot("codex", "ship"));
        let d = seats_decide("surf-ab12", &seen, &personas, "grok").unwrap();
        assert_eq!(
            d.counted,
            "grok for ship, codex for ship; 1 persona or judge ballot left out"
        );
        assert!(seats_decide("surf-ab12", &[], &personas, "grok")
            .unwrap_err()
            .starts_with("no seat voted on surf-ab12"));
    }

    #[test]
    fn a_push_is_free_cited_or_the_persons_by_where_it_goes() {
        // The guard stands down when HOME is a temporary directory. Other tests
        // point it there, so this one waits for that lock.
        let _g = env_guard();
        let p = push_call("cd ~/Git/x && LJOS_CITE=surf-ab12 git -C sub push origin main").unwrap();
        assert_eq!(p.dir.as_deref(), Some("sub"));
        assert_eq!(p.args, ["origin", "main"]);
        assert_eq!(p.cite.as_deref(), Some("surf-ab12"));
        assert_eq!(
            push_call("cd repo && git push").unwrap().dir.as_deref(),
            Some("repo")
        );
        assert!(push_call("git commit -m 'then git push'").is_none());
        assert_eq!(
            remote_slug("git@github.com:HaoZeke/ljos.git"),
            Some(("HaoZeke".into(), "ljos".into()))
        );
        assert_eq!(
            remote_slug("https://gitlab.com/group/sub/proj"),
            Some(("sub".into(), "proj".into()))
        );
        let args = |a: &[&str]| a.iter().map(|s| s.to_string()).collect::<Vec<_>>();
        let facts = |access: Access, released: bool| PushFacts {
            slug: Some(("HaoZeke".into(), "notes".into())),
            access,
            released,
        };
        assert_eq!(
            push_tier(&args(&["origin", "main"]), &facts(Access::Exclusive, false)),
            PushTier::Free
        );
        let unread = PushFacts {
            slug: None,
            access: Access::Unknown,
            released: false,
        };
        assert_eq!(
            push_tier(&args(&[]), &unread),
            PushTier::Free,
            "an unreadable owner does not ask"
        );
        assert_eq!(
            push_tier(&args(&["upstream", "develop"]), &unread),
            PushTier::Free
        );
        for access in [
            Access::Exclusive,
            Access::Shared,
            Access::Foreign,
            Access::Unknown,
        ] {
            assert_eq!(
                push_tier(&args(&["origin", "main"]), &facts(access, true)),
                PushTier::Free,
                "{access:?}"
            );
        }
        assert_eq!(push_tier(&args(&["--tags"]), &unread), PushTier::Free);
        assert_eq!(
            push_tier(&args(&["--follow-tags", "origin", "main"]), &unread),
            PushTier::Free
        );
        assert!(matches!(
            push_tier(&args(&["--mirror", "origin"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(&args(&["--force-with-lease"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(
                &args(&["--force-with-lease=main:abc123", "origin", "main"]),
                &unread
            ),
            PushTier::Person(_)
        ));
        assert_eq!(
            push_tier(&args(&["-u", "origin", "feature"]), &unread),
            PushTier::Free
        );
        assert_eq!(
            push_tier(&args(&["--force-with-lease", "origin", "feature"]), &unread),
            PushTier::Free,
            "a lease push onto a feature branch runs"
        );
        assert!(matches!(
            push_tier(
                &args(&["--force-with-lease", "origin", "+feature"]),
                &unread
            ),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(
                &args(&["--force-with-lease", "origin", "HEAD:develop"]),
                &unread
            ),
            PushTier::Person(_)
        ));
        assert_eq!(
            push_tier(&args(&["--force-if-includes"]), &unread),
            PushTier::Free
        );
        assert!(matches!(
            push_tier(&args(&["--force-with-lease", "--force"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(&args(&["-f"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(&args(&["origin", "--delete", "old"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(&args(&["origin", ":old"]), &unread),
            PushTier::Person(_)
        ));
        assert!(matches!(
            push_tier(
                &args(&["origin", "+main"]),
                &facts(Access::Exclusive, false)
            ),
            PushTier::Person(_)
        ));
        let alone = serde_json::json!({"push": true, "mine": true, "alone": true});
        assert_eq!(access_of(&alone), Access::Exclusive);
        let org = serde_json::json!({"push": true, "mine": false, "alone": true});
        assert_eq!(access_of(&org), Access::Shared);
        assert_eq!(
            access_of(&serde_json::json!({"push": false})),
            Access::Foreign
        );
        let fact = serde_json::json!({
            "kind": "lesson", "ts": "2026-10-02T00:00:00Z",
            "entities": [repo_entity("HaoZeke", "Notes"), "horizon:standing"],
            "facts": {"push": true, "mine": true, "alone": true, "released": false}
        });
        let older = serde_json::json!({
            "kind": "lesson", "ts": "2026-09-01T00:00:00Z",
            "entities": ["repo:haozeke/notes"],
            "facts": {"push": false}
        });
        let v = repo_facts_in(&[older, fact.clone()], "haozeke", "notes").unwrap();
        assert_eq!(access_of(&v), Access::Exclusive, "the latest claim answers");
        assert!(repo_facts_in(&[fact], "haozeke", "other").is_none());
        assert!(repo_fact_text("HaoZeke", "notes", &v).contains("a branch or tag push runs"));
        let deny = Rule {
            pattern: "x".into(),
            verdict: "deny".into(),
            reason: "r".into(),
        };
        assert_eq!(
            gate_push(Some(&deny), "git push", None),
            Some(deny.clone()),
            "a deny is the rule's own"
        );
        assert_eq!(gate_push(None, "git push", None), None);
        for line in [
            "git push --force origin main",
            "git push -f origin main",
            "git push origin +main",
            "git push origin --delete old",
            "git push origin :old",
            "git push --mirror origin",
            "git push origin :refs/tags/v1",
        ] {
            let gated = gate_push(None, line, None);
            assert!(
                gated
                    .as_ref()
                    .is_some_and(|r| { r.verdict == "ask" && r.pattern == "built-in push" }),
                "{line} -> {gated:?}"
            );
        }
        let cited = "LJOS_CITE=gpr_optim-1yg5 git push upstream develop";
        let refused = gate_push(None, cited, None).unwrap();
        assert_eq!(
            (refused.verdict.as_str(), refused.pattern.as_str()),
            ("deny", "built-in push cite")
        );
        assert!(
            refused
                .reason
                .starts_with("LJOS_CITE=gpr_optim-1yg5 does not stand: "),
            "{}",
            refused.reason
        );
        assert!(gate_push(None, "git push -u origin feature/x", None).is_none());
        for tags in [
            "git push --tags",
            "git push --follow-tags",
            "git push --follow-tags origin main",
            "git push origin v1.0.0",
            "git push origin tag v1.0.0",
            "git push origin refs/tags/v1.0.0",
        ] {
            assert!(gate_push(None, tags, None).is_none(), "{tags}");
        }
        let never = Rule {
            pattern: "*--force*".into(),
            verdict: "deny".into(),
            reason: "Never force.".into(),
        };
        assert_eq!(
            gate_push(Some(&never), "git push --force origin main", None)
                .as_ref()
                .map(|r| r.verdict.as_str()),
            Some("deny")
        );
        let trust = Rule {
            pattern: "git push*".into(),
            verdict: "ask".into(),
            reason: "A push is the trust gate.".into(),
        };
        for line in [
            "git push",
            "git push origin main",
            "git push -u origin feature/x",
        ] {
            let gated = gate_push(Some(&trust), line, None);
            assert!(gated.is_none(), "{line} stayed {gated:?}");
            let ruled = ruled_verdict(std::slice::from_ref(&trust), line);
            let gated = gate_push(ruled.as_ref(), line, None);
            assert!(gated.is_none(), "{line} via ruled_verdict stayed {gated:?}");
        }
        let gated = gate_push(Some(&trust), cited, None);
        assert_eq!(gated.map(|r| r.pattern), Some("built-in push cite".into()));
        let codex = hook_call(
            r#"{"hook_event_name":"PreToolUse","session_id":"c-1","turn_id":"t-1","tool_name":"Bash","tool_input":{"command":"git push"}}"#,
        );
        let gated = gate_push(
            ruled_verdict(std::slice::from_ref(&trust), &codex.cue).as_ref(),
            &codex.cue,
            None,
        );
        let said = hook_output_ruled(&codex, "", gated.as_ref());
        assert!(
            !said.contains("ask the person") && !said.contains("could not be read"),
            "{said}"
        );
        let cited = hook_call(
            r#"{"hook_event_name":"PreToolUse","session_id":"c-1","turn_id":"t-1","tool_name":"Bash","tool_input":{"command":"LJOS_CITE=gpr_optim-1yg5 git push upstream develop"}}"#,
        );
        let gated = gate_push(
            ruled_verdict(std::slice::from_ref(&trust), &cited.cue).as_ref(),
            &cited.cue,
            None,
        );
        assert_eq!(
            gated.map(|r| r.verdict),
            Some("deny".into()),
            "a cite that does not stand"
        );
        for line in ["git status", "git commit -m save", "cargo build", "rg foo"] {
            let ruled = ruled_verdict(&[], line);
            let gated = gate_push(ruled.as_ref(), line, None);
            assert!(gated.is_none(), "{line} -> {gated:?}");
            let with_rule = gate_push(
                ruled_verdict(std::slice::from_ref(&trust), line).as_ref(),
                line,
                None,
            );
            assert!(
                with_rule.is_none(),
                "{line} under git push* -> {with_rule:?}"
            );
        }
        let forced = gate_push(Some(&trust), "git push --force origin main", None);
        assert!(
            forced.as_ref().is_some_and(|r| r.verdict == "ask"),
            "{forced:?}"
        );
        assert!(
            validate_rule(&trust).is_err(),
            "git push* is refused at write time"
        );
        assert!(validate_rule(&Rule {
            pattern: "*--force*".into(),
            verdict: "deny".into(),
            reason: "Never force.".into(),
        })
        .is_ok());
        assert!(validate_rule(&Rule {
            pattern: "git push origin *".into(),
            verdict: "ask".into(),
            reason: "the command was `git push origin feature/x`".into(),
        })
        .is_err());
    }

    #[test]
