    /// The kept prompt makes a sentence the person's, so no tool call may
    /// replace it: not by naming the runtime directory that holds it, not
    /// by a relative name or a glob, and not through a file tool that
    /// names its target `path`.
    #[test]
    fn the_kept_prompt_and_its_directory_are_guarded() {
        let _g = env_guard();
        let prev = std::env::var_os("XDG_RUNTIME_DIR");
        // SAFETY: under env_guard, and restored below.
        unsafe { std::env::set_var("XDG_RUNTIME_DIR", "/run/user/1000") };
        for line in [
            "mv /tmp/p /run/user/1000/ljos/latest-prompt",
            "ln -sf /tmp/p $XDG_RUNTIME_DIR/ljos/latest-prompt.bind",
            "touch -r /tmp/p ${XDG_RUNTIME_DIR}/ljos/latest-prompt",
            "mv /run/user/1000/ljos /run/user/1000/ljos.old",
            "rm -rf $XDG_RUNTIME_DIR/ljos/",
            "ln -s /tmp/fake ${XDG_RUNTIME_DIR}/ljos",
            "cd /run/user/1000/ljos && printf plant > latest-prompt",
            "cp /tmp/bind ./latest-prompt.bind",
            "cp /tmp/p $XDG_RUNTIME_DIR/ljos/latest-pr*",
        ] {
            assert!(seat_guard(line).is_some(), "allowed: {line}");
        }
        for line in [
            "cat /run/user/1000/ljos/latest-prompt",
            "ls $XDG_RUNTIME_DIR/ljos",
            "cargo test -p ljos latest_prompt",
            "git -C /home/u/src/ljos status",
        ] {
            assert!(seat_guard(line).is_none(), "refused: {line}");
        }
        let mcp = hook_call(
            r#"{"hook_event_name":"PreToolUse","tool_name":"mcp__fs__write_file","tool_input":{"path":"/run/user/1000/ljos/latest-prompt","content":"it's the person's words"}}"#,
        );
        assert!(seat_guard(&mcp.cue).is_some(), "allowed: {}", mcp.cue);
        let read = hook_call(
            r#"{"hook_event_name":"PreToolUse","tool_name":"Grep","tool_input":{"path":"/run/user/1000/ljos","pattern":"x"}}"#,
        );
        assert!(seat_guard(&read.cue).is_none(), "refused: {}", read.cue);
        unsafe {
            match prev {
                Some(v) => std::env::set_var("XDG_RUNTIME_DIR", v),
                None => std::env::remove_var("XDG_RUNTIME_DIR"),
            }
        }
    }

    #[test]
    fn the_seat_guards_its_own_law() {
        // The guard stands down when HOME is a temporary directory. Other tests
        // point it there, so this one waits for that lock.
        let _g = env_guard();
        assert!(seat_guard("cp /tmp/shim ~/.local/bin/ljos").is_some());
        assert!(seat_guard("printf x > /home/u/.local/bin/ljos").is_some());
        assert!(seat_guard("cat /tmp/x > ~/.gemini/config/hooks.json").is_some());
        assert!(seat_guard("sed -i s/a/b/ ~/.codex/hooks.json").is_some());
        assert!(seat_guard("write_to_file /home/u/.local/bin/ljos").is_some());
        assert!(
            seat_guard("cat ~/.gemini/config/hooks.json").is_none(),
            "reading is fine"
        );
        for path in [
            "~/.cursor/hooks.json",
            "~/.codeium/windsurf/hooks.json",
            "~/.factory/hooks.json",
            "~/.kiro/hooks/ljos.json",
            "~/.copilot/hooks/ljos.json",
            "~/.qwen/settings.json",
            "~/.config/crush/crush.json",
            "~/Documents/Cline/Hooks",
            "~/Documents/Cline/Hooks/PreToolUse",
            "~/.augment/settings.json",
            "~/.augment/ljos-guard-auggie.sh",
            "~/.config/amp/settings.json",
            "~/.config/amp/ljos-guard-amp.sh",
            "~/.agents/plugins/ljos/hooks/hooks.json",
            "~/.openhands/hooks.json",
            "~/.gemini/settings.json",
        ] {
            assert!(
                seat_guard(&format!("sed -i s/a/b/ {path}")).is_some(),
                "{path}"
            );
            assert!(
                seat_guard(&format!("cat {path}")).is_none(),
                "reading {path}"
            );
        }
        assert!(seat_guard("sed -i s/a/b/ ~/notes/hooks.json").is_none());
        assert!(seat_guard("sha256sum ~/.local/bin/ljos ~/.local/bin/ljos.bak").is_none());
        assert!(
            seat_guard("cp ~/.local/bin/ljos /tmp/copy").is_some(),
            "a writer naming it is refused"
        );
        assert!(seat_guard("printf x > /run/user/1000/ljos/latest-prompt").is_some());
        assert!(seat_guard("printf x > /run/user/1000/ljos/latest-prompt.bind").is_some());
        assert!(seat_guard("ljos onboard --harness grok").is_none());
        assert!(seat_guard("cargo build --release").is_none());
        assert!(!is_seat_path("~/.local/bin/ljos.bak"));
        let edit = hook_call_as(
            r##"{"toolCall":{"name":"write_to_file","args":{"TargetFile":"/home/u/.local/bin/ljos","CodeContent":"#!/bin/sh"}},"conversationId":"c"}"##,
            Some("PreToolUse"),
        );
        assert_eq!(edit.cue, "write_to_file /home/u/.local/bin/ljos");
    }

    /// agy 1.4.3 names the file `Path` for `write_file` and `edit_file`.
    /// The guard read neither, so it saw those calls with no path. These
    /// are the PreToolUse payloads cell w4 of willma-20261020f sent (no
    /// `error` field, so a call before the tool runs), with the run's home
    /// and file text shortened.
    #[test]
    fn an_agy_file_tool_names_its_path_to_the_guard() {
        // The guard stands down when HOME is a temporary directory. Other tests
        // point it there, so this one waits for that lock.
        let _g = env_guard();
        let write = hook_call(
            r##"{"artifactDirectoryPath":"/h/.gemini/antigravity-cli/brain/6839fd1e","conversationId":"6839fd1e","modelName":"gemini-3.1-pro-low","stepIdx":8,"toolCall":{"args":{"Content":"import re\n","Overwrite":false,"Path":"/h/work/slug.py"},"name":"write_file"},"transcriptPath":"/h/.gemini/antigravity-cli/brain/6839fd1e/.system_generated/logs/transcript_full.jsonl","workspacePaths":["/h/work"]}"##,
        );
        assert_eq!(write.event, "PreToolUse");
        assert_eq!(write.cue, "write_file /h/work/slug.py");
        let edit = hook_call(
            r##"{"artifactDirectoryPath":"/h/.gemini/antigravity-cli/brain/6839fd1e","conversationId":"6839fd1e","modelName":"gemini-3.1-pro-low","stepIdx":18,"toolCall":{"args":{"Path":"/h/work/slug.py","Replacement":"import re\n","Target":"import os\n"},"name":"edit_file"},"transcriptPath":"/h/.gemini/antigravity-cli/brain/6839fd1e/.system_generated/logs/transcript_full.jsonl","workspacePaths":["/h/work"]}"##,
        );
        assert_eq!(edit.event, "PreToolUse");
        assert_eq!(edit.cue, "edit_file /h/work/slug.py");
        // The same call aimed at the seat's own binary is refused.
        let own = hook_call(
            r##"{"conversationId":"6839fd1e","toolCall":{"args":{"Content":"#!/bin/sh\n","Overwrite":true,"Path":"/home/u/.local/bin/ljos"},"name":"write_file"},"workspacePaths":["/h/work"]}"##,
        );
        assert_eq!(own.cue, "write_file /home/u/.local/bin/ljos");
        assert!(seat_guard(&own.cue).is_some(), "{}", own.cue);
        let own = hook_call(
            r##"{"conversationId":"6839fd1e","toolCall":{"args":{"Path":"/home/u/.local/bin/ljos","Replacement":"x","Target":"y"},"name":"edit_file"},"workspacePaths":["/h/work"]}"##,
        );
        assert!(seat_guard(&own.cue).is_some(), "{}", own.cue);
        // Reading a file names no write.
        let read = hook_call(
            r##"{"conversationId":"6839fd1e","toolCall":{"args":{"Path":"/home/u/.local/bin/ljos"},"name":"view_file"},"workspacePaths":["/h/work"]}"##,
        );
        assert_eq!(read.cue, "view_file");
    }

