        assert_eq!(format_sweep(None), "");
        assert_eq!(
            format_sweep(Some(&serde_json::json!({"lapsed": 0, "forgotten": 0}))),
            ""
        );
        let line = format_sweep(Some(&serde_json::json!({"lapsed": 2, "forgotten": 1})));
        assert!(line.contains("2 reviews lapsed"), "{line}");
