    #[test]
    fn a_deed_the_pusher_minted_does_not_carry_a_push() {
        let _env = env_guard();
        let dir = tempfile::tempdir().unwrap();
        let bin = dir.path().join("bin");
        std::fs::create_dir_all(&bin).unwrap();
        use std::os::unix::fs::PermissionsExt;
        for (name, body) in [
            ("deedar", "#!/bin/sh\nexit 0\n"),
            ("vissue", "#!/bin/sh\nexit 1\n"),
        ] {
            let path = bin.join(name);
            std::fs::write(&path, body).unwrap();
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        let tracker = dir.path().join("tracker");
        std::fs::create_dir_all(&tracker).unwrap();
        // The fakes stand in for deedar and vissue. Their directory is in
        // front of PATH, and any other directory that holds those binaries
        // but not cat or sh is left out. cat stays findable.
        let hidden = super::path_without(&["deedar", "vissue"]);
        let mut path = std::ffi::OsString::from(&bin);
        path.push(":");
        path.push(&hidden);
        let _bins = super::set_path(&path);
        let _held = HoldEnv::set(&[("VISSUE_ROOT", tracker.to_str().unwrap())]);
        let said = cite_stands("deed-file-self-minted").unwrap_err();
        assert!(said.contains("a deed alone does not stand"), "{said}");
        assert!(said.contains("another seat"), "{said}");
    }

    #[test]
    fn a_busy_writer_is_not_an_absent_one() {
        let refused = anyhow::Error::new(packset_client::Error::Bad(
            "http://127.0.0.1:8761/v1/search: 503: packsetd is busy".into(),
        ));
        assert!(writer_busy(&refused));
        assert!(!writer_unreachable(&refused));
        let raw = ureq::Response::new(503, "Service Unavailable", "busy").unwrap();
        let status = anyhow::Error::new(packset_client::Error::Http(Box::new(
            ureq::Error::Status(503, raw),
        )));
        assert!(writer_busy(&status));
        let other = anyhow::Error::new(packset_client::Error::Bad(
            "http://127.0.0.1:8761/v1/search: 400: q required".into(),
        ));
        assert!(!writer_busy(&other));
    }

