    /// A fake tracker on PATH: `show` answers as told, `claim` logs its
    /// argv and the identity it was given.
    fn fake_vissue(dir: &std::path::Path, show_ok: bool, claim_ok: bool) -> std::path::PathBuf {
        let log = dir.join("calls.log");
        let script = format!(
            "#!/bin/sh\necho \"$* VISSUE_AGENT=${{VISSUE_AGENT:-}}\" >> '{}'\ncase \"$1\" in\n  show) {} ;;\n  claim) {} ;;\nesac\nexit 0\n",
            log.display(),
            if show_ok { "echo '{}'" } else { "exit 1" },
            if claim_ok { "echo claimed" } else { "echo refused >&2; exit 1" },
        );
        let path = dir.join("vissue");
        std::fs::write(&path, script).unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        log
    }

    /// A fake `deedar` that logs its arguments and prints a bridge.
    fn fake_deedar(dir: &std::path::Path) -> std::path::PathBuf {
        let log = dir.join("deedar.log");
        let script = format!(
            "#!/bin/sh\necho \"deedar $*\" >> '{}'\ncase \"$1\" in\n  log) echo 'from size=3 root=aa'; echo 'to size=5 root=bb' ;;\n  check) echo '2 deeds proven against a log of 5 entries, root bb' ;;\nesac\nexit 0\n",
            log.display()
        );
        let path = dir.join("deedar");
        std::fs::write(&path, script).unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755)).unwrap();
        }
        log
    }

